function importRows(rows){orders=rows.map((r,i)=>rowMap(r,i)).filter(r=>r.name);customers=buildGroups(orders);selected='';states=new Map();logs=[];$('detail').classList.add('hidden');$('empty').classList.remove('hidden');$('search').value='';$('filter').value='all';updateList();toast('Imported '+orders.length+' 邮寄 rows for '+customers.length+' customer groups')}
$('file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{let data;if(/\.csv$/i.test(f.name)){data=csv(await f.text()).slice(1)}else{data=(await readShippingXlsx(await f.arrayBuffer())).slice(1)}importRows(data);$('filename').textContent=f.name+' · 邮寄 only'}catch(err){toast('Import failed: '+err.message)}};
