$('clear').onclick=()=>{orders=[];customers=[];selected='';states=new Map();logs=[];$('detail').classList.add('hidden');$('empty').classList.remove('hidden');$('filename').textContent='Only the 邮寄 sheet will be imported';updateList();toast('Session cleared')};
$('search').oninput=updateList;$('filter').onchange=updateList;for(const n of ['Items','Source','Review'])$('tab'+n).onclick=()=>showTab(n);
$('checkAll').onclick=()=>{const g=current();if(!g)return;const s=state(g);g.items.forEach((_,i)=>s.checks[i]=true);s.verified=false;draw()};
$('reviewDone').onclick=()=>{const g=current();if(!g)return;save();const s=state(g);if(g.issues.some((_,i)=>!s.resolved[i]))return toast('Acknowledge every review flag first');s.reviewed=true;s.verified=false;draw();toast('Review confirmed. Now verify physical items.')};
$('confirmPacking').onclick=()=>{const g=current();if(!g)return;save();const s=state(g);if(!s.reviewed)return toast('Open Exceptions & payment and confirm review first');if(!g.items.length||g.items.some((_,i)=>!s.checks[i]))return toast('Check each item before confirming');if(g.items.some((item,i)=>!Number.isInteger(Number(s.qtyOverride[i]??item.qty))||Number(s.qtyOverride[i]??item.qty)<1))return toast('Enter verified quantities for every product line');if(g.items.some(i=>i.missing)&&!s.notes.trim())return toast('Document how missing-stock items were resolved in reviewer notes');s.verified=true;draw();toast('Bag verification recorded in this session')};
$('adjustment').oninput=()=>{totals();save()};$('fee').oninput=()=>{totals();save()};
$('prepare').onclick=()=>{const g=current();if(!g)return;save();const s=state(g);if(!s.verified)return toast('Verify review and bag contents first');if(!num(s.weight)||!num(s.length)||!num(s.width)||!num(s.height))return toast('Enter positive package measurements');if(g.rows.some(r=>!r.amountValid))return toast('Source amount needs correction before preparing');const lines=g.items.map((i,n)=>'• '+i.text+' — 已核对 '+(s.qtyOverride[n]??i.qty)+' 件').join('\n');s.draft=g.name+' 您好！\n\n您的商品已整理，请核对：\n'+lines+'\n\n商品合计：'+usd(g.total)+'\n调整/抵扣：'+usd(s.adjustment)+'\n运费：'+usd(s.fee)+'\n暂计应付：'+usd(g.total+s.adjustment+s.fee)+'\n\n请核对商品信息，谢谢！';$('draft').value=s.draft;$('draftBox').classList.remove('hidden');logs.push({timestamp:new Date().toISOString(),customer:g.name,source_rows:g.rows.map(r=>r.row).join('|'),merchandise:g.total,adjustment:s.adjustment,shipping_fee:s.fee,provisional_due:g.total+s.adjustment+s.fee,payment:s.payment,weight_kg:s.weight,length_in:s.length,width_in:s.width,height_in:s.height,status:'Draft prepared — not shipped',notes:s.notes});toast('Draft prepared, no postage or messages sent')};
$('copy').onclick=async()=>{if($('draftBox').classList.contains('hidden'))return toast('Prepare a draft first');try{await navigator.clipboard.writeText($('draft').value);toast('Copied for manual WeChat sending')}catch{toast('Please select and copy message manually')}};
$('export').onclick=()=>{if(!logs.length)return toast('No drafts to export yet');const keys=Object.keys(logs[0]),rows=[keys,...logs.map(o=>keys.map(k=>o[k]))],file='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),blob=new Blob([file],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='yiyi-shipping-draft-log.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
